files.content:
* { box-sizing: border-box; }
:root {
  color-scheme: light;
  --ink: #182b3a;
  --muted: #657987;
  --paper: #fffdf7;
  --line: #d9e2df;
  --mint: #b9ecd8;
  --coral: #f17d68;
  --navy: #244257;
}
body {
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: #d8efe5;
  background-image: linear-gradient(135deg, transparent 25%, #c5e7d9 25%, #c5e7d9 50%, transparent 50%, transparent 75%, #c5e7d9 75%);
  background-size: 32px 32px;
  color: var(--ink);
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 16px;
}
.card {
  width: min(100%, 520px);
  padding: clamp(24px, 6vw, 42px);
  border: 3px solid var(--ink);
  border-radius: 10px;
  background: var(--paper);
  box-shadow: 8px 8px 0 var(--ink);
}
.pixel-mark {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  border: 3px solid var(--ink);
  border-radius: 8px;
  background: var(--mint);
  font-size: 26px;
  font-weight: 800;
}
.eyebrow {
  margin: 24px 0 4px;
  color: #477461;
  font-size: 14px;
  font-weight: 750;
  letter-spacing: .1em;
  text-transform: uppercase;
}
h1 { margin: 0; font-size: clamp(32px, 9vw, 44px); line-height: 1.1; letter-spacing: -.04em; }
.intro { margin: 12px 0 28px; color: var(--muted); line-height: 1.55; }
label { display: block; margin: 18px 0 8px; font-weight: 700; }
.range-note { margin-left: 5px; color: var(--muted); font-size: 14px; font-weight: 500; }
textarea, input {
  display: block;
  width: 100%;
  border: 2px solid var(--line);
  border-radius: 7px;
  background: #fff;
  color: var(--ink);
  font: inherit;
}
textarea { min-height: 112px; padding: 13px; line-height: 1.5; resize: vertical; }
input { max-width: 140px; min-height: 48px; padding: 8px 12px; }
textarea::placeholder { color: #82939d; }
textarea:focus, input:focus { border-color: #477461; outline: 3px solid #b9ecd8; outline-offset: 2px; }
.actions { display: flex; gap: 12px; margin: 24px 0 26px; }
button {
  min-height: 48px;
  padding: 10px 18px;
  border: 2px solid var(--ink);
  border-radius: 7px;
  background: var(--coral);
  color: #182b3a;
  cursor: pointer;
  font: inherit;
  font-weight: 750;
  transition: transform .12s ease, box-shadow .12s ease, background-color .12s ease;
}
button:hover { transform: translateY(-2px); box-shadow: 0 3px 0 var(--ink); }
button:active { transform: translateY(1px); box-shadow: none; }
button:focus-visible { outline: 3px solid #477461; outline-offset: 3px; }
button.secondary { background: var(--mint); }
.result-heading { display: flex; align-items: center; justify-content: space-between; }
.result-heading label { margin: 0 0 8px; }
button.copy-button { min-height: 36px; padding: 5px 12px; border-width: 1px; background: var(--paper); font-size: 14px; }
#result { background: #f2f8f4; }
.status { min-height: 22px; margin: 8px 0 0; color: #477461; font-size: 14px; }
footer { margin-top: 16px; color: var(--muted); font-size: 13px; line-height: 1.5; text-align: center; }
@media (max-width: 380px) { .actions { flex-direction: column; } .actions button { width: 100%; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; } }

const message = document.querySelector("#message");
const shiftInput = document.querySelector("#shift");
const result = document.querySelector("#result");
const status = document.querySelector("#status");

function transform(direction) {
  const shift = Number(shiftInput.value);
  if (!Number.isInteger(shift) || shift < 1 || shift > 25) {
    shiftInput.setCustomValidity("Enter a whole number from 1 to 25.");
    shiftInput.reportValidity();
    return;
  }
  shiftInput.setCustomValidity("");
  const offset = direction * shift;
  result.value = [...message.value].map(char => {
    const code = char.charCodeAt(0);
    const base = code >= 65 && code <= 90 ? 65 : code >= 97 && code <= 122 ? 97 : -1;
    return base < 0 ? char : String.fromCharCode(((code - base + offset + 26) % 26) + base);
  }).join("");
  status.textContent = direction === 1 ? "Message encoded." : "Message decoded.";
}

shiftInput.addEventListener("input", () => shiftInput.setCustomValidity(""));
document.querySelector("#encode").addEventListener("click", () => transform(1));
document.querySelector("#decode").addEventListener("click", () => transform(-1));
document.querySelector("#copy").addEventListener("click", async () => {
  if (!result.value) {
    status.textContent = "There is no result to copy yet.";
    return;
  }
  try {
    await navigator.clipboard.writeText(result.value);
    status.textContent = "Result copied.";
  } catch {
    result.focus();
    result.select();
    status.textContent = "Select the result and copy it with your keyboard.";
  }
});
